	@Test
	void nestedUnionCursorRetainsEveryConstituentAfterPreflightScopeCloses() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		AtomicReference<StatementInput> captured = new AtomicReference<>();
		AtomicReference<CloseableIteration<Statement>> retainedCursor = new AtomicReference<>();
		AtomicInteger witnessRows = new AtomicInteger();
		backing.onEstimate = input -> {
			captured.set(input);
			retainedCursor.set(input.openCursor());
			try (CloseableIteration<Statement> cursor = input.openCursor()) {
				while (cursor.hasNext()) {
					cursor.next();
					witnessRows.incrementAndGet();
				}
			}
		};
		SailSourceBranch first = branch(backing);
		SailSourceBranch second = branch(backing);
		SailSourceBranch third = branch(backing);
		UnionSailSource union = new UnionSailSource(first, new UnionSailSource(second, third));
		Statement firstStatement = statement("first");
		Statement secondStatement = statement("second");
		Statement thirdStatement = statement("third");

		try (union) {
			add(first, firstStatement);
			add(second, secondStatement);
			add(third, thirdStatement);

			union.prepare();

			assertThat(witnessRows).hasValue(3);
			assertThat(backing.estimatedRows).hasValue(3);
			assertThat(captured.get()).isNotNull();
			assertThat(retainedCursor.get()).isNotNull();
			assertThat(readAll(retainedCursor.get()))
					.containsExactly(firstStatement, secondStatement, thirdStatement);
		}
	}

