	@Test
	void failedRepeatedPreparationDoesNotReleaseOwnerBeforePriorPreparation() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch branch = branch(backing);
		RuntimeException estimateFailure = new RuntimeException("second streaming estimate failed");
		backing.failEstimateAt = 2;
		backing.estimateFailure = estimateFailure;

		try {
			add(branch, statement("first-generation"));
			branch.prepare();
			assertThat(backing.estimatedRows).hasValue(1);
			assertThat(backing.liveSinkPreparations).hasValue(1);
			assertThat(backing.retainedOwnerCount).hasValue(1);

			add(branch, statement("later-generation"));
			assertThatThrownBy(branch::prepare).isSameAs(estimateFailure);

			assertThat(backing.estimatedRows).hasValue(3);
			assertThat(backing.liveSinkPreparations).hasValue(1);
			assertThat(backing.retainedOwnerCloses).hasValue(0);
		} finally {
			branch.close();
		}

		assertThat(backing.liveSinkPreparations).hasValue(0);
		assertThat(backing.retainedOwnerCloses).hasValue(1);
		assertThat(backing.ownerClosedWhilePrepared).hasValue(0);
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void cancelingFrozenBatchReleasesPreparationBeforeOwnerCleanupCallback() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch branch = branch(backing);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		AtomicBoolean callbackOpenedDataset = new AtomicBoolean();
		AtomicInteger preparedAtCallback = new AtomicInteger(-1);
		backing.onOwnerClose = () -> {
			preparedAtCallback.set(backing.liveSinkPreparations.get());
			try {
				Future<?> acquisition = executor.submit(() -> {
					try (SailDataset ignored = branch.dataset(IsolationLevels.NONE)) {
						callbackOpenedDataset.set(true);
					}
				});
				acquisition.get(5, TimeUnit.SECONDS);
			} catch (Exception failure) {
				throw new AssertionError("The owner cleanup callback could not acquire the branch after release",
						failure);
			}
		};

		try {
			add(branch, statement("cancelled-batch"));
			branch.prepare();
			assertThat(backing.liveSinkPreparations).hasValue(1);

			SailSource.FlushBatch batch = branch.freezeForFlush();
			batch.close();

			assertThat(backing.retainedOwnerCloses).hasValue(1);
			assertThat(preparedAtCallback).hasValue(0);
			assertThat(callbackOpenedDataset).isTrue();
		} finally {
			branch.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void autoFlushReturnsWhileAncestorPreparedSinkStillOwnsBranchGuard() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch parent = branch(backing);
		SailSourceBranch child = new SailSourceBranch(parent, new DynamicModelFactory(), true);
		SailSource.FlushBatch emptyBatch = child.freezeForFlush();
		add(child, statement("later-child-generation"));
		emptyBatch.close();

		ExecutorService executor = Executors.newFixedThreadPool(2);
		CountDownLatch parentPrepared = new CountDownLatch(1);
		CountDownLatch releaseParent = new CountDownLatch(1);
		AtomicBoolean returnedBeforeRelease = new AtomicBoolean();
		Future<?> parentTask = executor.submit(() -> {
			try (SailSink sink = parent.sink(IsolationLevels.SERIALIZABLE)) {
				sink.prepare();
				parentPrepared.countDown();
				await(releaseParent, "parent preparation release");
			}
		});
		Future<?> autoFlushTask = null;
		try {
			await(parentPrepared, "ancestor prepared sink");
			autoFlushTask = executor.submit(child::autoFlush);
			try {
				autoFlushTask.get(2, TimeUnit.SECONDS);
				returnedBeforeRelease.set(true);
			} catch (java.util.concurrent.TimeoutException blockedByAncestor) {
				// Release the held sink in finally before reporting the nonblocking contract failure.
			}
		} finally {
			releaseParent.countDown();
			parentTask.get(5, TimeUnit.SECONDS);
			if (autoFlushTask != null) {
				autoFlushTask.get(5, TimeUnit.SECONDS);
			}
			child.close();
			parent.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}

		assertThat(returnedBeforeRelease).as("child autoFlush should not wait for an ancestor's prepared sink")
				.isTrue();
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void autoFlushDoesNotWaitForAncestorOwnerResolution() throws Exception {
		RecordingStreamingSource terminal = new RecordingStreamingSource();
		terminal.nullOwnerReturnsNull = true;
		SailSourceBranch parent = branch(terminal);
		SailSourceBranch child = new SailSourceBranch(parent, new DynamicModelFactory(), true);
		Statement queued = statement("auto-flush-owner-resolution");
		SailSource.FlushBatch emptyBatch = child.freezeForFlush();
		add(child, queued);
		emptyBatch.close();

		AtomicReference<Thread> autoFlushThread = new AtomicReference<>();
		AtomicInteger autoFlushOwnerQueries = new AtomicInteger();
		AtomicInteger hookQuery = new AtomicInteger();
		AtomicBoolean hookActivated = new AtomicBoolean();
		CountDownLatch startParentPrepare = new CountDownLatch(1);
		CountDownLatch parentPrepared = new CountDownLatch(1);
		CountDownLatch releaseParent = new CountDownLatch(1);
		terminal.onNullOwnerQuery = thread -> {
			if (thread == autoFlushThread.get()) {
				int query = autoFlushOwnerQueries.incrementAndGet();
				if (query == 2 && hookActivated.compareAndSet(false, true)) {
					hookQuery.set(query);
					startParentPrepare.countDown();
					await(parentPrepared, "ancestor prepared sink during owner resolution");
				}
			}
		};

		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<?> parentTask = executor.submit(() -> {
			await(startParentPrepare, "owner-resolution hook");
			try (SailSink sink = parent.sink(IsolationLevels.SERIALIZABLE)) {
				sink.prepare();
				parentPrepared.countDown();
				await(releaseParent, "ancestor preparation release");
			}
		});
		Future<?> autoFlushTask = executor.submit(() -> {
			autoFlushThread.set(Thread.currentThread());
			child.autoFlush();
		});
		boolean returnedBeforeRelease = false;
		boolean queuedRowVisible = false;
		Throwable autoFlushFailure = null;
		try {
			try {
				autoFlushTask.get(2, TimeUnit.SECONDS);
				returnedBeforeRelease = releaseParent.getCount() == 1;
			} catch (java.util.concurrent.TimeoutException blockedByAncestor) {
				// Release the held sink in finally before reporting the liveness failure.
			} catch (java.util.concurrent.ExecutionException failure) {
				autoFlushFailure = failure.getCause();
			}
		} finally {
			startParentPrepare.countDown();
			releaseParent.countDown();
			parentTask.get(5, TimeUnit.SECONDS);
			try {
				autoFlushTask.get(5, TimeUnit.SECONDS);
			} catch (java.util.concurrent.ExecutionException failure) {
				if (autoFlushFailure == null) {
					autoFlushFailure = failure.getCause();
				}
			}
			try (SailDataset dataset = child.dataset(IsolationLevels.NONE)) {
				queuedRowVisible = readAll(dataset.getStatements(null, null, null)).contains(queued);
			}
			child.close();
			parent.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}

		assertThat(hookActivated).as("the autoFlush thread reached the second null-owner query").isTrue();
		assertThat(hookQuery).hasValue(2);
		assertThat(parentPrepared.getCount()).as("the hook prepared the parent through the public sink API").isZero();
		assertThat(returnedBeforeRelease).as("child autoFlush returned while the parent sink was still prepared")
				.isTrue();
		assertThat(queuedRowVisible).as("the real buffered child row remains visible").isTrue();
		assertThat(autoFlushFailure).isNull();
	}

