	private static void assertIndependentNestedFlushDoesNotPoisonOuterUnion(boolean legacy, boolean bulk)
			throws Exception {
		RecordingStreamingSource firstTerminal = new RecordingStreamingSource();
		RecordingStreamingSource additionalTerminal = new RecordingStreamingSource();
		RecordingStreamingSource independentTerminal = new RecordingStreamingSource();
		LegacyPreflightSource legacyTerminal = legacy ? new LegacyPreflightSource(independentTerminal) : null;
		SailSource independentBacking = legacy ? legacyTerminal : independentTerminal;
		SailSourceBranch first = branch(firstTerminal);
		SailSourceBranch additional = branch(additionalTerminal);
		SailSourceBranch independentParent = branch(independentBacking);
		SailSourceBranch independentChild = branch(independentParent);
		UnionSailSource outer = new UnionSailSource(first, additional);
		Statement outerPrimary = statement("independent-nested-outer-primary");
		Statement outerAdditional = statement("independent-nested-outer-additional");
		Statement independentAdded = statement("independent-nested-added");
		Statement parentExisting = statement("independent-nested-parent-existing");
		Statement independentRemoved = statement("independent-nested-removed");
		if (bulk) {
			independentTerminal.seed(independentRemoved);
		}
		AtomicBoolean callbackAttempted = new AtomicBoolean();
		AtomicBoolean independentFlushCompleted = new AtomicBoolean();
		AtomicReference<Throwable> independentFailure = new AtomicReference<>();
		AtomicReference<Throwable> outerFailure = new AtomicReference<>();
		firstTerminal.onSinkPrepare = () -> {
			if (callbackAttempted.compareAndSet(false, true)) {
				firstTerminal.onSinkPrepare = () -> {
				};
				try {
					independentChild.flush();
					independentParent.flush();
					independentFlushCompleted.set(true);
				} catch (Throwable failure) {
					independentFailure.set(failure);
				}
			}
		};

		List<Statement> childView = List.of();
		try (outer; independentChild; independentParent) {
			add(first, outerPrimary);
			add(additional, outerAdditional);
			if (bulk) {
				add(independentParent, parentExisting);
				addRemovalAndAddition(independentChild, independentRemoved, independentAdded);
			} else {
				add(independentChild, independentAdded);
			}
			try (SailDataset dataset = independentChild.dataset(IsolationLevels.NONE)) {
				childView = readAll(dataset.getStatements(null, null, null));
			}

			try {
				outer.flush();
			} catch (Throwable failure) {
				outerFailure.set(failure);
			}
		}

		assertThat(childView).as("the independent child exposes its real buffered statement before publication");
		if (bulk) {
			assertThat(childView).containsExactlyInAnyOrder(parentExisting, independentAdded);
		} else {
			assertThat(childView).containsExactly(independentAdded);
		}
		assertThat(callbackAttempted).as("outer primary preparation entered the independent nested flush callback")
				.isTrue();
		if (legacy) {
			assertThat(legacyTerminal.legacyCalls.get()).as("the independent legacy preflight boundary ran")
					.isGreaterThan(0);
			assertThat(legacyTerminal.legacyRows.get())
					.as("legacy preflight traversed the independent buffered row")
					.isGreaterThan(0);
		} else {
			assertThat(independentTerminal.estimateCalls.get())
					.as("the streaming nested control estimated its real input")
					.isGreaterThan(0);
			assertThat(independentTerminal.estimatedRows.get())
					.as("streaming preflight traversed the independent row")
					.isGreaterThan(0);
		}
		assertThat(independentFailure.get()).as("the independent nested flush must not inherit the outer frame")
				.isNull();
		assertThat(independentFlushCompleted).as("both independent child and parent flushes completed")
				.isTrue();
		assertThat(outerFailure.get()).as("the independent flush must not poison outer Union publication").isNull();
		assertThat(firstTerminal.committed).containsExactly(outerPrimary);
		assertThat(additionalTerminal.committed).containsExactly(outerAdditional);
		assertThat(firstTerminal.approvalCount(outerPrimary)).hasValue(1);
		assertThat(additionalTerminal.approvalCount(outerAdditional)).hasValue(1);
		if (bulk) {
			assertThat(independentTerminal.committed).containsExactlyInAnyOrder(parentExisting, independentAdded);
			assertThat(independentTerminal.committed).doesNotContain(independentRemoved);
			assertThat(independentTerminal.approvalCount(parentExisting)).hasValue(1);
		} else {
			assertThat(independentTerminal.committed).containsExactly(independentAdded);
		}
		assertThat(independentTerminal.approvalCount(independentAdded)).hasValue(1);
	}

	private static void assertCaughtIndependentPrepareFailureDoesNotPoisonOuterUnion(boolean legacy)
			throws Exception {
		RecordingStreamingSource firstTerminal = new RecordingStreamingSource();
		RecordingStreamingSource additionalTerminal = new RecordingStreamingSource();
		RecordingStreamingSource independentTerminal = new RecordingStreamingSource();
		SailSource independentBacking = legacy ? new LegacyPreflightSource(independentTerminal) : independentTerminal;
		SailSourceBranch first = branch(firstTerminal);
		SailSourceBranch additional = branch(additionalTerminal);
		SailSourceBranch independent = branch(independentBacking);
		UnionSailSource outer = new UnionSailSource(first, additional);
		RuntimeException independentPrepareMarker = new RuntimeException("independent sink preparation failed");
		independentTerminal.failSinkPrepareAt = 1;
		independentTerminal.sinkPrepareFailure = independentPrepareMarker;
		AtomicBoolean independentPrepareAttempted = new AtomicBoolean();
		AtomicReference<Throwable> independentPrepareFailure = new AtomicReference<>();
		firstTerminal.onSinkPrepare = () -> {
			firstTerminal.onSinkPrepare = () -> {
			};
			if (independentPrepareAttempted.compareAndSet(false, true)) {
				try {
					independent.prepare();
				} catch (Throwable failure) {
					independentPrepareFailure.set(failure);
				}
			}
		};

		Throwable outerPrepareFailure = null;
		try (outer; independent) {
			add(first, statement("independent-outer-primary"));
			add(additional, statement("independent-outer-additional"));
			add(independent, statement("independent-inner-write"));
			try {
				outer.prepare();
			} catch (Throwable failure) {
				outerPrepareFailure = failure;
			}
		}

		assertThat(independentPrepareAttempted).as("the first terminal invoked an independent public prepare")
				.isTrue();
		assertThat(independentTerminal.sinkPrepareCalls).as("the independent backing sink was really prepared")
				.hasValue(1);
		assertThat(independentPrepareFailure.get())
				.as("the injected inner sink failure was caught by the callback")
				.isSameAs(independentPrepareMarker);
		if (legacy) {
			LegacyPreflightSource decorator = (LegacyPreflightSource) independentBacking;
			assertThat(decorator.legacyCalls.get()).as("the independent legacy admission boundary was used")
					.isGreaterThan(0);
			assertThat(decorator.legacyRows.get()).as("the independent legacy estimate included its real row")
					.isGreaterThan(0);
		} else {
			assertThat(independentTerminal.estimateCalls.get()).as("the independent streaming estimator ran")
					.isGreaterThan(0);
			assertThat(independentTerminal.estimatedRows.get())
					.as("the independent estimator traversed its real row")
					.isGreaterThan(0);
		}
		assertThat(firstTerminal.sinkPrepareCalls).as("the outer primary sink preparation completed").hasValue(1);
		assertThat(additionalTerminal.sinkPrepareCalls)
				.as("the outer additional sink was prepared after the caught error")
				.hasValue(1);
		assertThat(outerPrepareFailure).as("a caught independent failure cannot poison the outer Union")
				.isNull();
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void caughtIndependentAdmissionMutationDoesNotPoisonOuterUnion() throws Exception {
		RecordingStreamingSource firstTerminal = new RecordingStreamingSource();
		RecordingStreamingSource additionalTerminal = new RecordingStreamingSource();
		RecordingStreamingSource independentTerminal = new RecordingStreamingSource();
		SailSourceBranch first = branch(firstTerminal);
		SailSourceBranch additional = branch(additionalTerminal);
		SailSourceBranch independent = branch(independentTerminal);
		UnionSailSource outer = new UnionSailSource(first, additional);
		Statement initial = statement("independent-admission-initial");
		Statement injected = statement("independent-admission-injected");
		Changeset pending = (Changeset) independent.sink(IsolationLevels.NONE);
		pending.approve(initial);
		AtomicReference<Thread> outerPrepareThread = new AtomicReference<>();
		AtomicBoolean admissionHookActivated = new AtomicBoolean();
		AtomicBoolean mutationApplied = new AtomicBoolean();
		AtomicBoolean pendingContainsInjected = new AtomicBoolean();
		AtomicReference<Throwable> independentPrepareFailure = new AtomicReference<>();
		AtomicReference<Throwable> mutationFailure = new AtomicReference<>();
		independentTerminal.onPreflightScopeIsActive = thread -> {
			if (thread == outerPrepareThread.get() && admissionHookActivated.compareAndSet(false, true)) {
				try {
					pending.approve(injected);
					mutationApplied.set(true);
				} catch (Throwable failure) {
					mutationFailure.set(failure);
				}
			}
		};
		AtomicBoolean independentPrepareAttempted = new AtomicBoolean();
		firstTerminal.onSinkPrepare = () -> {
			firstTerminal.onSinkPrepare = () -> {
			};
			if (independentPrepareAttempted.compareAndSet(false, true)) {
				try {
					independent.prepare();
				} catch (Throwable failure) {
					independentPrepareFailure.set(failure);
					if (mutationFailure.get() == null && failure instanceof SailConflictException) {
						mutationFailure.set(failure);
					}
				}
			}
		};

		Throwable outerPrepareFailure = null;
		try (outer; independent; pending) {
			outerPrepareThread.set(Thread.currentThread());
			add(first, statement("admission-outer-primary"));
			add(additional, statement("admission-outer-additional"));
			try {
				outer.prepare();
			} catch (Throwable failure) {
				outerPrepareFailure = failure;
			}
			pendingContainsInjected.set(pending.hasApproved(injected.getSubject(), injected.getPredicate(),
					injected.getObject(), new Resource[] { injected.getContext() }));
		}

		assertThat(independentTerminal.estimateCalls.get())
				.as("the independent streaming admission estimated its input")
				.isGreaterThan(0);
		assertThat(independentTerminal.estimatedRows.get())
				.as("the independent admission traversed its initial row")
				.isGreaterThan(0);
		assertThat(admissionHookActivated).as("mutation ran from scope validation after input estimation").isTrue();
		assertThat(mutationApplied).as("the public pending sink accepted the new statement").isTrue();
		assertThat(pendingContainsInjected).as("the mutation changed the existing pending sink").isTrue();
		assertThat(independentPrepareAttempted).isTrue();
		assertThat(mutationFailure.get()).as("the independent stale-input conflict was caught")
				.isInstanceOf(SailConflictException.class);
		assertThat(firstTerminal.sinkPrepareCalls).hasValue(1);
		assertThat(additionalTerminal.sinkPrepareCalls).as("the outer additional sink still prepares")
				.hasValue(1);
		assertThat(independentPrepareFailure.get()).isInstanceOf(SailConflictException.class);
		assertThat(outerPrepareFailure).as("a caught independent admission conflict cannot poison the outer Union")
				.isNull();
	}

