	private static void assertAutoFlushSkipsBusyAncestorWhenCursorCloses(boolean failRawClose) throws Exception {
		RecordingStreamingSource terminal = new RecordingStreamingSource();
		SailSourceBranch parent = branch(terminal);
		Statement queued = statement("busy-auto-flush-target");
		RemovalCloseHook hook = new RemovalCloseHook(queued);
		SailSourceBranch child = new SailSourceBranch(parent, hook.factory(), true);
		SailSource.FlushBatch emptyBatch = child.freezeForFlush();
		add(child, queued);
		emptyBatch.close();
		AtomicReference<Thread> autoFlushThread = new AtomicReference<>();
		AtomicReference<StatementInput> capturedInput = new AtomicReference<>();
		AtomicReference<CloseableIteration<Statement>> retainedCursor = new AtomicReference<>();
		AtomicBoolean activeHook = new AtomicBoolean();
		AtomicBoolean cursorClosedByScope = new AtomicBoolean();
		AtomicInteger estimateRowsAtActiveHook = new AtomicInteger();
		AtomicInteger rawCloseCalls = new AtomicInteger();
		CountDownLatch startParentPrepare = new CountDownLatch(1);
		CountDownLatch parentPrepared = new CountDownLatch(1);
		CountDownLatch releaseParent = new CountDownLatch(1);
		RuntimeException closeMarker = new RuntimeException("busy autoFlush raw cursor close failed");
		AtomicReference<Throwable> autoFlushFailure = new AtomicReference<>();
		terminal.onEstimate = input -> {
			if (Thread.currentThread() == autoFlushThread.get()) {
				capturedInput.set(input);
			}
		};
		terminal.onPreflightScopeIsActive = thread -> {
			if (thread == autoFlushThread.get() && activeHook.compareAndSet(false, true)) {
				estimateRowsAtActiveHook.set(terminal.estimatedRows.get());
				CloseableIteration<Statement> cursor = capturedInput.get().openCursor();
				boolean foundTarget = false;
				while (cursor.hasNext()) {
					if (queued.equals(cursor.next())) {
						foundTarget = true;
						break;
					}
				}
				if (!foundTarget) {
					cursor.close();
					throw new AssertionError("The retained cursor did not read the queued target");
				}
				retainedCursor.set(cursor);
				startParentPrepare.countDown();
				await(parentPrepared, "parent prepared while the child validates its admitted scope");
			}
		};
		terminal.onPreflightScopeClose = scopeId -> {
			if (activeHook.get() && retainedCursor.get() != null
					&& cursorClosedByScope.compareAndSet(false, true)) {
				retainedCursor.get().close();
			}
		};
		hook.callback = () -> {
			rawCloseCalls.incrementAndGet();
			if (failRawClose) {
				throw closeMarker;
			}
		};
		hook.armed.set(true);

		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<?> parentTask = executor.submit(() -> {
			await(startParentPrepare, "scope hook starting parent preparation");
			try (SailSink sink = parent.sink(IsolationLevels.SERIALIZABLE)) {
				sink.prepare();
				parentPrepared.countDown();
				await(releaseParent, "parent prepared sink release");
			}
		});
		Future<?> autoFlushTask = executor.submit(() -> {
			autoFlushThread.set(Thread.currentThread());
			child.autoFlush();
		});
		boolean returnedBeforeRelease = false;
		try {
			try {
				autoFlushTask.get(2, TimeUnit.SECONDS);
				returnedBeforeRelease = releaseParent.getCount() == 1;
			} catch (java.util.concurrent.TimeoutException blockedAncestor) {
				// Release the prepared parent in finally before reporting a liveness failure.
			} catch (java.util.concurrent.ExecutionException failure) {
				autoFlushFailure.set(failure.getCause());
				returnedBeforeRelease = releaseParent.getCount() == 1;
			}
		} finally {
			releaseParent.countDown();
			try {
				parentTask.get(5, TimeUnit.SECONDS);
			} finally {
				try {
					autoFlushTask.get(5, TimeUnit.SECONDS);
				} catch (java.util.concurrent.ExecutionException failure) {
					autoFlushFailure.compareAndSet(null, failure.getCause());
				}
				child.close();
				parent.close();
				executor.shutdownNow();
				executor.awaitTermination(5, TimeUnit.SECONDS);
			}
		}

		assertThat(terminal.estimatedRows.get()).as("the actual streaming estimator traversed the queued target")
				.isGreaterThan(0);
		assertThat(estimateRowsAtActiveHook.get()).as("the scope hook ran after target traversal").isGreaterThan(0);
		assertThat(hook.exhausted).as("the real estimator exhausted the target cursor").isTrue();
		assertThat(activeHook).as("the child reached admitted scope validation").isTrue();
		assertThat(parentPrepared.getCount()).as("the public parent sink really prepared").isZero();
		assertThat(returnedBeforeRelease).as("autoFlush completed while the ancestor remained prepared").isTrue();
		assertThat(cursorClosedByScope).as("the retained raw cursor closed during the busy-skip cleanup").isTrue();
		assertThat(hook.fired).as("the target raw iterator closed exactly once").isTrue();
		assertThat(rawCloseCalls).hasValue(1);
		if (failRawClose) {
			assertThat(autoFlushFailure.get()).as("the raw cursor close marker is reported exactly once")
					.isSameAs(closeMarker);
		} else {
			assertThat(autoFlushFailure.get()).as("a clean busy-ancestor skip returns without failure").isNull();
		}
	}

