	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void successfulRefreshDefersRetiredScopeOwnerClosePastEarlierPreparation() throws Exception {
		RecordingStreamingSource terminal = new RecordingStreamingSource();
		terminal.seed(statement("scope-owner-observed"));
		SailSourceBranch parent = branch(terminal);
		SailSourceBranch child = branch(parent);
		SailDataset parentDatasetOwner = parent.dataset(IsolationLevels.SNAPSHOT);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		AtomicInteger firstScopeCloseCount = new AtomicInteger();
		AtomicInteger preparedAtDatasetClose = new AtomicInteger(-1);
		AtomicBoolean datasetOwnerClosed = new AtomicBoolean();
		AtomicReference<Future<?>> datasetCloseTask = new AtomicReference<>();
		Throwable secondPrepareFailure = null;
		try {
			assertThat(readAll(parentDatasetOwner.getStatements(null, null, null)))
					.containsExactly(statement("scope-owner-observed"));
			add(child, statement("scope-owner-first-generation"));
			child.prepare();
			assertThat(terminal.preflightScopeOpens).hasValue(1);
			int estimatesBeforeRefresh = terminal.estimateCalls.get();
			int traversedBeforeRefresh = terminal.estimatedRows.get();
			add(child, statement("scope-owner-later-generation"));
			terminal.onPreflightScopeClose = scopeId -> {
				if (scopeId == 1) {
					firstScopeCloseCount.incrementAndGet();
					preparedAtDatasetClose.set(terminal.liveSinkPreparations.get());
					Future<?> closeTask = executor.submit(() -> {
						parentDatasetOwner.close();
						datasetOwnerClosed.set(true);
					});
					datasetCloseTask.set(closeTask);
					awaitFuture(closeTask, "scope retirement dataset owner close");
				}
			};
			try {
				child.prepare();
			} catch (Throwable failure) {
				secondPrepareFailure = failure;
			}
			assertThat(terminal.estimateCalls).hasValue(estimatesBeforeRefresh + 1);
			assertThat(terminal.estimatedRows.get() - traversedBeforeRefresh).isPositive();
		} finally {
			try {
				child.close();
			} finally {
				Future<?> closeTask = datasetCloseTask.get();
				if (closeTask != null) {
					closeTask.get(5, TimeUnit.SECONDS);
				}
				if (!datasetOwnerClosed.get()) {
					parentDatasetOwner.close();
				}
				parent.close();
				executor.shutdownNow();
				executor.awaitTermination(5, TimeUnit.SECONDS);
			}
		}
		assertThat(secondPrepareFailure).isNull();
		assertThat(firstScopeCloseCount).hasValue(1);
		assertThat(datasetOwnerClosed).isTrue();
		assertThat(preparedAtDatasetClose)
				.as("the retired owner closes after the earlier prepared sink releases its reservation")
				.hasValue(0);
		assertThat(terminal.preflightScopeCloses)
				.as("the retired scope and the replacement scope each close exactly once")
				.hasValue(2);
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void failedUnionAdmissionDefersCandidateCleanupUntilEarlierPreparationReleases() throws Exception {
		RecordingStreamingSource firstTerminal = new RecordingStreamingSource();
		RecordingStreamingSource secondTerminal = new RecordingStreamingSource();
		Statement observed = statement("failed-union-owner-observed");
		firstTerminal.seed(observed);
		SailSourceBranch first = branch(firstTerminal);
		SailSourceBranch second = branch(secondTerminal);
		UnionSailSource union = new UnionSailSource(first, second);
		SailDataset parentDatasetOwner = first.dataset(IsolationLevels.SNAPSHOT);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		AtomicInteger candidateScopeCloseCount = new AtomicInteger();
		AtomicInteger candidateOwnerCloseCount = new AtomicInteger();
		AtomicInteger preparedAtDatasetClose = new AtomicInteger(-1);
		AtomicBoolean datasetOwnerClosed = new AtomicBoolean();
		AtomicBoolean closeScheduled = new AtomicBoolean();
		AtomicReference<Future<?>> datasetCloseTask = new AtomicReference<>();
		AtomicReference<Throwable> asynchronousCloseFailure = new AtomicReference<>();
		RuntimeException estimateFailure = new RuntimeException("second union estimate failed");
		secondTerminal.failEstimateAt = 1;
		secondTerminal.estimateFailure = estimateFailure;
		SailSink earlierPreparedSink = null;
		Throwable unionPrepareFailure = null;
		int firstRowsBeforeUnion = -1;
		int secondRowsBeforeUnion = -1;
		try {
			assertThat(readAll(parentDatasetOwner.getStatements(null, null, null))).containsExactly(observed);
			add(first, statement("first-union-candidate"));
			add(second, statement("second-union-candidate"));
			earlierPreparedSink = first.sink(IsolationLevels.SERIALIZABLE);
			earlierPreparedSink.prepare();
			int candidateScopeId = firstTerminal.preflightScopeOpens.get() + 1;
			int candidateOwnerId = firstTerminal.retainedOwnerCount.get() + 1;
			firstRowsBeforeUnion = firstTerminal.estimatedRows.get();
			secondRowsBeforeUnion = secondTerminal.estimatedRows.get();
			firstTerminal.onPreflightScopeClose = scopeId -> {
				if (scopeId == candidateScopeId) {
					candidateScopeCloseCount.incrementAndGet();
					closeDatasetOwnerFromCallback(executor, parentDatasetOwner, firstTerminal, closeScheduled,
							datasetCloseTask, datasetOwnerClosed, preparedAtDatasetClose, asynchronousCloseFailure);
				}
			};
			firstTerminal.onRetainedOwnerClose = ownerId -> {
				if (ownerId == candidateOwnerId) {
					candidateOwnerCloseCount.incrementAndGet();
					closeDatasetOwnerFromCallback(executor, parentDatasetOwner, firstTerminal, closeScheduled,
							datasetCloseTask, datasetOwnerClosed, preparedAtDatasetClose, asynchronousCloseFailure);
				}
			};

			try {
				union.prepare();
			} catch (Throwable failure) {
				unionPrepareFailure = failure;
			}
			assertThat(firstTerminal.estimatedRows.get() - firstRowsBeforeUnion).isPositive();
			assertThat(secondTerminal.estimatedRows.get() - secondRowsBeforeUnion).isPositive();
		} finally {
			try {
				if (earlierPreparedSink != null) {
					earlierPreparedSink.close();
				}
			} finally {
				try {
					Future<?> closeTask = datasetCloseTask.get();
					if (closeTask != null) {
						closeTask.get(5, TimeUnit.SECONDS);
					}
				} catch (Throwable failure) {
					asynchronousCloseFailure.compareAndSet(null, failure);
				} finally {
					if (!datasetOwnerClosed.get()) {
						parentDatasetOwner.close();
					}
					union.close();
					executor.shutdownNow();
					executor.awaitTermination(5, TimeUnit.SECONDS);
				}
			}
		}
		assertThat(unionPrepareFailure).isSameAs(estimateFailure);
		assertThat(unionPrepareFailure.getSuppressed()).isEmpty();
		assertThat(candidateScopeCloseCount).hasValue(1);
		assertThat(candidateOwnerCloseCount).hasValue(1);
		assertThat(datasetOwnerClosed).isTrue();
		assertThat(preparedAtDatasetClose).hasValue(0);
		assertThat(asynchronousCloseFailure.get()).isNull();
	}

	@Test
	@Timeout(value = 20, unit = TimeUnit.SECONDS)
	void sameInputExhaustedCursorCloseFailureIsSuppressedOnEstimateFailure() throws Exception {
		RecordingStreamingSource terminal = new RecordingStreamingSource();
		Statement observed = statement("same-input-close-observed");
		Statement removed = statement("same-input-close-removed");
		Statement approved = statement("same-input-close-approved");
		Statement later = statement("same-input-close-later");
		terminal.seed(observed);
		terminal.seed(removed);
		SailSourceBranch parent = branch(terminal);
		SailDataset datasetOwner = parent.dataset(IsolationLevels.SNAPSHOT);
		RemovalCloseHook hook = new RemovalCloseHook(approved);
		SailSourceBranch child = new SailSourceBranch(parent, hook.factory(), false);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		AtomicInteger rawCloseCount = new AtomicInteger();
		AtomicInteger preparedAtRawClose = new AtomicInteger(-1);
		AtomicBoolean datasetOwnerClosed = new AtomicBoolean();
		AtomicReference<Future<?>> closeTask = new AtomicReference<>();
		AtomicReference<Throwable> asynchronousCloseFailure = new AtomicReference<>();
		RuntimeException estimateMarker = new RuntimeException("same-input estimate failed after cursor exhaustion");
		RuntimeException closeMarker = new RuntimeException("same-input raw cursor close failed");
		Throwable admissionFailure = null;
		Throwable finalReleaseFailure = null;
		Throwable parentCleanupFailure = null;
		int firstEstimateCalls = -1;
		int firstEstimateRows = -1;
		int rowsBeforeRefresh = -1;
		try {
			assertThat(readAll(datasetOwner.getStatements(null, null, null))).containsExactlyInAnyOrder(observed,
					removed);
			addRemovalAndAddition(child, removed, approved);
			int callsBeforeFirstPrepare = terminal.estimateCalls.get();
			int rowsBeforeFirstPrepare = terminal.estimatedRows.get();
			child.prepare();
			firstEstimateCalls = terminal.estimateCalls.get();
			firstEstimateRows = terminal.estimatedRows.get();
			assertThat(firstEstimateCalls - callsBeforeFirstPrepare).isPositive();
			assertThat(firstEstimateRows - rowsBeforeFirstPrepare).isPositive();
			assertThat(hook.fired).as("the first prepare leaves the close hook disarmed").isFalse();
			add(child, later);
			rowsBeforeRefresh = terminal.estimatedRows.get();
			hook.exhausted.set(false);
			terminal.failEstimateAt = firstEstimateCalls + 1;
			terminal.estimateFailure = estimateMarker;
			armCloseHookThatClosesDatasetThenThrows(hook, terminal, datasetOwner, executor, closeMarker,
					rawCloseCount, preparedAtRawClose, datasetOwnerClosed, closeTask, asynchronousCloseFailure);
			try {
				child.prepare();
			} catch (Throwable failure) {
				admissionFailure = failure;
			}
		} finally {
			try {
				try {
					child.close();
				} catch (Throwable failure) {
					finalReleaseFailure = failure;
				}
				captureCloseTaskFailure(closeTask, asynchronousCloseFailure);
				try {
					parent.close();
				} catch (Throwable failure) {
					parentCleanupFailure = failure;
				}
				captureCloseTaskFailure(closeTask, asynchronousCloseFailure);
				if (closeTask.get() == null && !datasetOwnerClosed.get()) {
					datasetOwner.close();
					datasetOwnerClosed.set(true);
				}
			} finally {
				hook.armed.set(false);
				executor.shutdownNow();
				executor.awaitTermination(5, TimeUnit.SECONDS);
			}
		}

		assertThat(terminal.estimateCalls).as("the changed generation reached its estimate failure")
				.hasValue(firstEstimateCalls + 1);
		assertThat(terminal.estimatedRows.get() - rowsBeforeRefresh)
				.as("the changed approved and deprecated input rows were traversed")
				.isPositive();
		assertThat(hook.exhausted).as("the approved raw cursor consumed the target and exhausted").isTrue();
		assertThat(hook.fired).as("the exhausted approved raw cursor was disposed").isTrue();
		assertThat(rawCloseCount).hasValue(1);
		assertThat(admissionFailure).isSameAs(estimateMarker);
		assertThat(preparedAtRawClose)
				.as("the retained input closes only after the earlier preparation releases")
				.hasValue(0);
		assertThat(datasetOwnerClosed).isTrue();
		assertThat(asynchronousCloseFailure.get()).isNull();
		assertThat(finalReleaseFailure).as("releasing the retained preparation succeeds").isNull();
		assertThat(parentCleanupFailure).isNull();
		assertThat(estimateMarker.getSuppressed()).containsExactly(closeMarker);
	}

	@Test
	@Timeout(value = 20, unit = TimeUnit.SECONDS)
	void failedUnionAdmissionSuppressesExhaustedCursorCloseFailureAfterPreparationRelease() throws Exception {
		RecordingStreamingSource firstTerminal = new RecordingStreamingSource();
		RecordingStreamingSource secondTerminal = new RecordingStreamingSource();
		Statement observed = statement("union-close-observed");
		Statement removed = statement("union-close-removed");
		Statement approved = statement("union-close-approved");
		Statement secondWrite = statement("union-close-second-write");
		firstTerminal.seed(observed);
		firstTerminal.seed(removed);
		RemovalCloseHook hook = new RemovalCloseHook(approved);
		SailSourceBranch first = new SailSourceBranch(firstTerminal, hook.factory(), false);
		SailSourceBranch second = branch(secondTerminal);
		UnionSailSource union = new UnionSailSource(first, second);
		SailDataset datasetOwner = first.dataset(IsolationLevels.SNAPSHOT);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		AtomicInteger rawCloseCount = new AtomicInteger();
		AtomicInteger preparedAtRawClose = new AtomicInteger(-1);
		AtomicBoolean datasetOwnerClosed = new AtomicBoolean();
		AtomicReference<Future<?>> closeTask = new AtomicReference<>();
		AtomicReference<Throwable> asynchronousCloseFailure = new AtomicReference<>();
		RuntimeException estimateMarker = new RuntimeException("second Union group estimate failed");
		RuntimeException closeMarker = new RuntimeException("Union approved cursor close failed");
		SailSink earlierPreparedSink = null;
		Throwable admissionFailure = null;
		Throwable finalReleaseFailure = null;
		Throwable unionCleanupFailure = null;
		int firstRowsBeforeAdmission = -1;
		int secondRowsBeforeAdmission = -1;
		int secondCallsBeforeAdmission = -1;
		try {
			assertThat(readAll(datasetOwner.getStatements(null, null, null)))
					.containsExactlyInAnyOrder(observed, removed);
			addRemovalAndAddition(first, removed, approved);
			add(second, secondWrite);
			earlierPreparedSink = first.sink(IsolationLevels.SERIALIZABLE);
			earlierPreparedSink.prepare();
			firstRowsBeforeAdmission = firstTerminal.estimatedRows.get();
			secondRowsBeforeAdmission = secondTerminal.estimatedRows.get();
			secondCallsBeforeAdmission = secondTerminal.estimateCalls.get();
			hook.exhausted.set(false);
			secondTerminal.failEstimateAt = secondCallsBeforeAdmission + 1;
			secondTerminal.estimateFailure = estimateMarker;
			armCloseHookThatClosesDatasetThenThrows(hook, firstTerminal, datasetOwner, executor, closeMarker,
					rawCloseCount, preparedAtRawClose, datasetOwnerClosed, closeTask, asynchronousCloseFailure);
			try {
				union.prepare();
			} catch (Throwable failure) {
				admissionFailure = failure;
			}
		} finally {
			try {
				if (earlierPreparedSink != null) {
					try {
						earlierPreparedSink.close();
					} catch (Throwable failure) {
						finalReleaseFailure = failure;
					}
				}
				captureCloseTaskFailure(closeTask, asynchronousCloseFailure);
				try {
					union.close();
				} catch (Throwable failure) {
					unionCleanupFailure = failure;
				}
				captureCloseTaskFailure(closeTask, asynchronousCloseFailure);
				if (closeTask.get() == null && !datasetOwnerClosed.get()) {
					datasetOwner.close();
					datasetOwnerClosed.set(true);
				}
			} finally {
				hook.armed.set(false);
				executor.shutdownNow();
				executor.awaitTermination(5, TimeUnit.SECONDS);
			}
		}

		assertThat(firstTerminal.estimatedRows.get() - firstRowsBeforeAdmission)
				.as("the first group exhausted its approved cursor")
				.isPositive();
		assertThat(secondTerminal.estimatedRows.get() - secondRowsBeforeAdmission)
				.as("the second group traversed rows before its injected estimate failure")
				.isPositive();
		assertThat(secondTerminal.estimateCalls).hasValue(secondCallsBeforeAdmission + 1);
		assertThat(hook.exhausted).as("the first group's approved raw cursor exhausted").isTrue();
		assertThat(hook.fired).as("the first group's raw cursor disposal ran").isTrue();
		assertThat(rawCloseCount).hasValue(1);
		assertThat(admissionFailure).isSameAs(estimateMarker);
		assertThat(preparedAtRawClose)
				.as("candidate cleanup waits until the earlier public preparation releases")
				.hasValue(0);
		assertThat(datasetOwnerClosed).isTrue();
		assertThat(asynchronousCloseFailure.get()).isNull();
		assertThat(finalReleaseFailure).as("releasing the earlier prepared sink succeeds").isNull();
		assertThat(unionCleanupFailure).isNull();
		assertThat(estimateMarker.getSuppressed()).containsExactly(closeMarker);
	}

	private static void armCloseHookThatClosesDatasetThenThrows(RemovalCloseHook hook,
			RecordingStreamingSource terminal, SailDataset datasetOwner, ExecutorService executor,
			RuntimeException closeMarker, AtomicInteger rawCloseCount, AtomicInteger preparedAtRawClose,
			AtomicBoolean datasetOwnerClosed, AtomicReference<Future<?>> closeTask,
			AtomicReference<Throwable> asynchronousCloseFailure) {
		hook.callback = () -> {
			rawCloseCount.incrementAndGet();
			preparedAtRawClose.set(terminal.liveSinkPreparations.get());
			Future<?> task = executor.submit(() -> {
				datasetOwner.close();
				datasetOwnerClosed.set(true);
			});
			closeTask.set(task);
			try {
				task.get(5, TimeUnit.SECONDS);
			} catch (Exception failure) {
				asynchronousCloseFailure.set(failure);
				throw new AssertionError("The raw cursor close could not retire the real parent dataset owner",
						failure);
			}
			throw closeMarker;
		};
		hook.armed.set(true);
	}

	private static void captureCloseTaskFailure(AtomicReference<Future<?>> closeTask,
			AtomicReference<Throwable> asynchronousCloseFailure) {
		Future<?> task = closeTask.get();
		if (task != null) {
			try {
				task.get(5, TimeUnit.SECONDS);
			} catch (Exception failure) {
				asynchronousCloseFailure.compareAndSet(null, failure);
			}
		}
	}

	private static void closeDatasetOwnerFromCallback(ExecutorService executor, SailDataset datasetOwner,
			RecordingStreamingSource terminal, AtomicBoolean scheduled, AtomicReference<Future<?>> closeTask,
			AtomicBoolean datasetOwnerClosed, AtomicInteger preparedAtClose,
			AtomicReference<Throwable> asynchronousFailure) {
		if (scheduled.compareAndSet(false, true)) {
			preparedAtClose.set(terminal.liveSinkPreparations.get());
			Future<?> task = executor.submit(() -> {
				datasetOwner.close();
				datasetOwnerClosed.set(true);
			});
			closeTask.set(task);
			try {
				task.get(5, TimeUnit.SECONDS);
			} catch (Exception failure) {
				asynchronousFailure.set(failure);
				throw new AssertionError("The retained parent dataset could not close from the cleanup callback",
						failure);
			}
		}
	}

	private static void awaitFuture(Future<?> future, String description) {
		try {
			future.get(5, TimeUnit.SECONDS);
		} catch (Exception failure) {
			throw new AssertionError("The retained parent dataset could not close after " + description, failure);
		}
	}

